// Идемпотентность: если внешний ID уже есть — не публикуем повторно
const row = $input.first().json;
if (!row || !row.id) {
  throw new Error('Publication not found or already processed');
}
if (row.external_post_id) {
  return [{ json: { ...row, skip: true } }];
}
if (!row.secret_ref) {
  throw new Error('No integration connection / secret_ref for channel');
}
const text = [row.body, (row.hashtags ?? []).map(h => `#${h}`).join(' ')].filter(Boolean).join('\n\n');
if (text.length > 4096) {
  throw new Error('Message exceeds Telegram 4096 char limit');
}
return [{ json: { ...row, text, skip: false } }];
